import{_ as e,o,c as t,a1 as i}from"./chunks/framework.BKrM4vFX.js";const k=JSON.parse('{"title":"Такском — интеграция чтения фискальных данных (API v2)","description":"Такском — интеграция чтения фискальных данных (API v2). © 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0 Основание — официальная документация Такском API Help v2 (авторизация/discovery, документы, частота опроса, границы инт","frontmatter":{"sourcePath":"docs/integration/taxcom.md"},"headers":[{"level":1,"title":"Такском — интеграция чтения фискальных данных (API v2)","slug":"Такском-интеграция-чтения-фискальных-данных-api-v2","link":"#Такском-интеграция-чтения-фискальных-данных-api-v2","children":[{"level":2,"title":"1. Адреса и запуск","slug":"_1-Адреса-и-запуск","link":"#_1-Адреса-и-запуск","children":[{"level":3,"title":"Docker / compose","slug":"docker-compose","link":"#docker-compose","children":[]}]},{"level":2,"title":"2. Login → Session-Token (5 минут, sliding)","slug":"_2-login-→-session-token-5-минут-sliding","link":"#_2-login-→-session-token-5-минут-sliding","children":[]},{"level":2,"title":"3. AccountList — договоры и права","slug":"_3-accountlist-договоры-и-права","link":"#_3-accountlist-договоры-и-права","children":[]},{"level":2,"title":"4. NewDocuments — 10 суток, 10 000, курсор по id","slug":"_4-newdocuments-10-суток-10-000-курсор-по-id","link":"#_4-newdocuments-10-суток-10-000-курсор-по-id","children":[]},{"level":2,"title":"5. Сценарии, часы и журнал","slug":"_5-Сценарии-часы-и-журнал","link":"#_5-Сценарии-часы-и-журнал","children":[]},{"level":2,"title":"6. Песочницы и mock control (не API провайдера)","slug":"_6-Песочницы-и-mock-control-не-api-провайдера","link":"#_6-Песочницы-и-mock-control-не-api-провайдера","children":[]},{"level":2,"title":"7. Что мок проверяет за вас: границы и проверка","slug":"_7-Что-мок-проверяет-за-вас-границы-и-проверка","link":"#_7-Что-мок-проверяет-за-вас-границы-и-проверка","children":[]},{"level":2,"title":"8. Ссылки","slug":"_8-Ссылки","link":"#_8-Ссылки","children":[]}]}],"relativePath":"docs/integration/taxcom.md","filePath":"docs/integration/taxcom.md"}'),a={name:"docs/integration/taxcom.md"};function c(n,s,d,l,r,p){return o(),t("div",null,[...s[0]||(s[0]=[i(`<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="Такском-интеграция-чтения-фискальных-данных-api-v2" tabindex="-1">Такском — интеграция чтения фискальных данных (API v2) <a class="header-anchor" href="#Такском-интеграция-чтения-фискальных-данных-api-v2" aria-label="Permalink to &quot;Такском — интеграция чтения фискальных данных (API v2)&quot;">​</a></h1><p>Основание — официальная документация Такском API Help v2 (авторизация/discovery, документы, частота опроса, границы интеграции). <a href="https://github.com/rucorp/mock-services/blob/main/protocols/taxcom-ofd.json" target="_blank" rel="noreferrer">Манифест</a>, <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/taxcom-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI 3.1</a>, <a href="./../../services/taxcom-mock/README">README сервиса и env</a>.</p><p><strong>Это чтение кабинета/ОФД, не печать чеков.</strong> Такском API v2.17 отдаёт фискальные документы, уже принятые ОФД. Создание/фискализация чека, возврат и callback печати в публичном срезе не найдены, поэтому write API <strong>не моделируется</strong>: известный маршрут с другим методом даёт <code>405</code>, неизвестный <code>/API/...</code> — <code>404</code>, обе с подсказкой. Это не Ferma, не АТОЛ Онлайн и не OKassa — не подменяйте их контракты именем Такском.</p><h2 id="_1-Адреса-и-запуск" tabindex="-1">1. Адреса и запуск <a class="header-anchor" href="#_1-Адреса-и-запуск" aria-label="Permalink to &quot;1. Адреса и запуск&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Назначение</th><th>База</th></tr></thead><tbody><tr><td>Production</td><td><code>https://api-lk-ofd.taxcom.ru</code></td></tr><tr><td>Тестовый контур</td><td><code>https://api-tlk-ofd.taxcom.ru</code></td></tr><tr><td>Локальный мок (auth + данные)</td><td><code>http://localhost:3109</code></td></tr></tbody></table><p>Общий путь методов — <code>/API/v2/...</code>. У провайдера авторизация и данные идут по одной базе, у мока — тоже один сервис, поэтому в адаптере достаточно одной базы.</p><p>Публичных тестовых <code>login</code>/<code>password</code>/<code>Integrator-ID</code> Такском <strong>не публикует</strong>: их выдаёт техподдержка/кабинет (<strong>[VERIFY]</strong>). В моке работают синтетические дефолты — они печатаются в стартовом логе и <strong>не являются реквизитами провайдера</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>taxcom-mock synthetic credentials (не реквизиты Такском):</span></span>
<span class="line"><span>  login=taxcommocktest password=mockpass123 Integrator-ID=TAXCOMMOCKTEST;</span></span>
<span class="line"><span>  Session-Token TTL 300s sliding (virtual clock)</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:taxcom</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # :3109, креды по умолчанию — синтетические</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:taxcom</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # HTTP selftest на эфемерном порту, без Docker</span></span></code></pre></div><p>Свои синтетические значения задаются env (<code>MOCK_TAXCOM_LOGIN</code>, <code>MOCK_TAXCOM_PASSWORD</code>, <code>MOCK_TAXCOM_INTEGRATOR_ID</code>); заданные через env креды в логе скрываются. В <code>owned</code>-режиме <code>POST /sandboxes</code> генерирует собственные mock-реквизиты песочницы. Production-креды не коммитьте и не отправляйте в мок.</p><h3 id="docker-compose" tabindex="-1">Docker / compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to &quot;Docker / compose&quot;">​</a></h3><p>Сервис зарегистрирован в корневом <code>docker-compose.yml</code> (профиль по умолчанию, bind <code>127.0.0.1:3109</code>) и во внешнем <code>docker-compose.include.yml</code> (профиль <code>mock</code>). <code>Dockerfile</code> содержит <code>EXPOSE 3109</code>, healthcheck опрашивает <code>:3109/health</code>. Публикация GHCR-образа и смена release pin — отдельный процесс владельца: закреплённый релиз ещё не содержит этот адаптер, поэтому для include соберите локальный образ и снимите digest override:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mock-services:taxcom-local</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MOCK_IMAGE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mock-services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOCK_IMAGE_TAG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">taxcom-local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOCK_IMAGE_DIGEST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&#39;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.include.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mock</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> taxcom-mock</span></span></code></pre></div><p>В приложении из другого контейнера используйте <code>http://taxcom-mock:3109</code>, а не его <code>localhost</code>. Для удалённого доступа задайте <code>MOCK_TAXCOM_PUBLIC_BASE_URL</code> и TLS/reverse proxy; control endpoints в интернет не выставляйте.</p><h2 id="_2-login-→-session-token-5-минут-sliding" tabindex="-1">2. Login → Session-Token (5 минут, sliding) <a class="header-anchor" href="#_2-login-→-session-token-5-минут-sliding" aria-label="Permalink to &quot;2. Login → Session-Token (5 минут, sliding)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:3109</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/API/v2/Login&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Integrator-ID: TAXCOMMOCKTEST&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;login&quot;:&quot;taxcommocktest&quot;,&quot;password&quot;:&quot;mockpass123&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;JSON.parse(fs.readFileSync(0,&quot;utf8&quot;)).token&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/API/v2/AccountList&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Session-Token: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><ul><li><code>Integrator-ID</code> — <strong>заголовок</strong>, обязателен на <code>POST /API/v2/Login</code>; без него и с неизвестным значением — <code>401</code> с <code>field: Integrator-ID</code>.</li><li>Тело — JSON. <strong>[VERIFY]</strong> Официальная схема <code>Login_Request</code> (приложение к API Help) в публичной HTML-части не раскрыта, поэтому реализована консервативная форма <code>{&quot;login&quot;: &quot;...&quot;, &quot;password&quot;: &quot;...&quot;}</code>: оба поля обязательны, неизвестные ключи отклоняются <code>400</code> с пометкой <code>verify: &quot;Login_Request [VERIFY]&quot;</code>. Не подставляйте сюда поля из сторонних SDK — при выдаче доступа форму нужно пересверить.</li><li>Ответ несёт временный marker в поле <code>token</code> (<strong>[VERIFY]</strong> имя поля тоже не раскрыто срезом). Далее все вызовы несут заголовок <code>Session-Token</code>; <code>Authorization: Bearer</code> не подходит.</li><li>TTL — <strong>300 секунд (5 минут)</strong>, sliding от последнего успешного использования, на <strong>виртуальных часах</strong> стенда. Просроченный маркер → <code>HTTP 401</code> (<code>errorCodeId: 401</code>), сессия удаляется. Настройка — <code>MOCK_TAXCOM_SESSION_TTL_SECS</code> (целые секунды 1..31536000, <code>0</code> запрещён).</li><li><strong>[FORK]</strong> Повторный Login выдаёт <strong>новый</strong> marker, а прежний продолжает действовать до своего TTL. Срез формулирует иначе: «Повторный Login не выдаёт новый marker, пока предыдущий действителен». Решение владельца зафиксировано как документированный форк и требует пересверки на стенде провайдера.</li><li>Mock-only заголовки ответа Login: <code>X-Mock-Token-Expires-At</code>, <code>X-Mock-Token-Ttl-Secs</code> — удобно для тестов TTL без ожидания.</li><li>Отзыв маркера воспроизводится reset&#39;ом песочницы, импортом <code>/mock/state</code> и ротацией кредов (<code>/sandboxes/me/reset-creds</code>).</li></ul><h2 id="_3-accountlist-договоры-и-права" tabindex="-1">3. AccountList — договоры и права <a class="header-anchor" href="#_3-accountlist-договоры-и-права" aria-label="Permalink to &quot;3. AccountList — договоры и права&quot;">​</a></h2><p><code>GET /API/v2/AccountList</code> → массив договоров/личных кабинетов, доступных пользователю, и его права. Синтетический каталог <strong>[FORK]</strong> (независимо копируется в каждую песочницу):</p><ul><li><code>an=1000001</code> — «Демо кабинет Такском»: ККТ <code>0000000000000001</code> с доступом и ККТ <code>0000000000000002</code> без согласия (её документы в выдачу не попадают);</li><li><code>an=1000002</code> — «Кабинет без доступной ККТ»: договор виден, но <code>NewDocuments</code> с этим <code>an</code> даёт <strong>3106</strong>;</li><li><code>an=1000003</code> — «Нет согласия на данные»: в <code>AccountList</code> отсутствует, адресный запрос — <code>404</code>.</li></ul><p>Поля ответа (<code>an</code>, <code>inn</code>, <code>kpp</code>, <code>name</code>, <code>rights</code>) — локальная форма <strong>[FORK]</strong>: срез подтверждает «договоры/личные кабинеты и права пользователя», но схему не раскрывает. Внутренний признак <code>accessible</code> наружу не выдаётся.</p><h2 id="_4-newdocuments-10-суток-10-000-курсор-по-id" tabindex="-1">4. NewDocuments — 10 суток, 10 000, курсор по id <a class="header-anchor" href="#_4-newdocuments-10-суток-10-000-курсор-по-id" aria-label="Permalink to &quot;4. NewDocuments — 10 суток, 10 000, курсор по id&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/API/v2/NewDocuments&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Session-Token: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/API/v2/NewDocuments?an=1000001&amp;id=doc-0013&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Session-Token: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Query: <code>an</code> — необязательный номер договора, <code>id</code> — курсор. Алгоритм обхода:</p><ol><li>Первый вызов — <strong>без <code>id</code></strong>.</li><li>Ответ — JSON-массив документов, отсортированный по <strong>времени приёма Такскомом</strong> (<code>receivedAt</code>), а не по фискальному <code>dateTime</code>.</li><li>Запомните <code>id</code> последнего полученного документа и передайте его в <code>id</code> следующего запроса; период/фильтры/песочницу не меняйте.</li><li>Пустой массив (<code>[]</code>, <code>HTTP 200</code>) — хвост достигнут, обход завершён.</li><li>За вызов возвращается не более <strong>10 000</strong> документов; метод отдаёт только документы, принятые за последние <strong>10 суток</strong> (нижняя граница окна включена — <strong>[FORK]</strong>).</li><li>Провайдер рекомендует опрашивать <strong>не чаще раза в минуту</strong>. Это совет документации, а не жёсткое правило мока: мок не throttles запросы, но и новые документы сам не печатает — демо-набор фиксирован.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;id&quot;: &quot;doc-0002&quot;, &quot;an&quot;: &quot;1000001&quot;, &quot;kktRegNumber&quot;: &quot;0000000000000001&quot;,</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;receipt&quot;,</span></span>
<span class="line"><span>    &quot;receivedAt&quot;: &quot;2026-10-02T09:05:00.000Z&quot;, &quot;dateTime&quot;: &quot;2026-10-02T09:08:00.000Z&quot;,</span></span>
<span class="line"><span>    &quot;fiscalDocumentNumber&quot;: 2, &quot;fiscalSign&quot;: &quot;1000000002&quot;, &quot;shiftNumber&quot;: 1,</span></span>
<span class="line"><span>    &quot;operationType&quot;: 1, &quot;totalSum&quot;: 12345, &quot;cashSum&quot;: 0, &quot;electronicSum&quot;: 12345,</span></span>
<span class="line"><span>    &quot;items&quot;: [{ &quot;name&quot;: &quot;Тестовый товар&quot;, &quot;price&quot;: 12345, &quot;quantity&quot;: 1, &quot;sum&quot;: 12345 }]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>Типы документов из среза: открытие смены (<code>openShift</code>), закрытие смены (<code>closeShift</code>), состояние расчётов (<code>currentStateReport</code>), чек (<code>receipt</code>), чек коррекции (<code>receiptCorrection</code>), БСО (<code>bso</code>), БСО коррекции (<code>bsoCorrection</code>). Имена типов и полей — <strong>[FORK]</strong> (схема <code>NewDocuments_Response</code>, Приложение №12, в HTML-части не отображается). <strong>Суммы — в целых копейках</strong> (конвенция ФФД: <code>12345</code> = 123,45 ₽); срез Такском единицы не закрепляет, поэтому это локальная договорённость <strong>[FORK]</strong>. Возврат прихода — уже существующий ФД с <code>operationType=2</code>. <strong>[VERIFY]</strong> Ставки НДС <code>22%</code> и <code>22-122</code> в агрегатах смены (новое в v2.17) срезом упомянуты, но имена полей не раскрыты — в моке не моделируются.</p><p>Ошибки из среза:</p><table tabindex="0"><thead><tr><th>Код</th><th>HTTP</th><th>Когда</th></tr></thead><tbody><tr><td><code>3106</code></td><td>403</td><td>Нет доступной ККТ (например, <code>an</code> договора без видимых касс)</td></tr><tr><td><code>2203</code></td><td>400</td><td>Некорректный курсор <code>id</code>, в том числе документ вне окна 10 суток</td></tr></tbody></table><p>Соответствие кодов HTTP-статусам срезом не закреплено — это <strong>[VERIFY]</strong>/[FORK] мока; конверт ошибки <code>{errorCodeId, message, field, hint, doc}</code> локальный, для остальных случаев <code>errorCodeId</code> равен HTTP-статусу.</p><h2 id="_5-Сценарии-часы-и-журнал" tabindex="-1">5. Сценарии, часы и журнал <a class="header-anchor" href="#_5-Сценарии-часы-и-журнал" aria-label="Permalink to &quot;5. Сценарии, часы и журнал&quot;">​</a></h2><ul><li><code>X-Mock-Scenario: fail</code> → <code>HTTP 500</code> без изменения данных;</li><li><code>hang</code> → ожидание до закрытия соединения клиентом, задавайте timeout;</li><li><code>duplicate</code> → повтор первой строки с <strong>тем же <code>id</code>/ФД/ФП</strong> до курсорной нарезки; лимит 10 000 сохраняется, курсор разрешается по <strong>первому</strong> вхождению <code>id</code> <strong>[FORK]</strong>. Задавайте сценарий на всех запросах одного обхода;</li><li><code>latency:200ms</code>, <code>http-500</code>, <code>http-504</code> — общий транспортный chaos ядра;</li><li><code>POST /mock/scenarios</code> <code>{&quot;scenario&quot;:&quot;fail&quot;,&quot;target&quot;:&quot;read&quot;,&quot;times&quot;:1}</code> — одноразовый отказ; targets <code>auth</code>, <code>read</code>, <code>*</code>; есть <code>persistent</code> и <code>match</code>;</li><li><code>GET/DELETE /mock/scenarios</code> — правила/история и очистка;</li><li><code>POST /mock/time</code> <code>{&quot;advance&quot;:&quot;+6m&quot;}</code> — истечение <code>Session-Token</code> без ожидания пяти минут; <code>{&quot;advance&quot;:&quot;+11d&quot;}</code> — документы выпадают из окна 10 суток, и <code>NewDocuments</code> возвращает пустой массив.</li></ul><p>Часы, fixtures, сценарии и журнал изолируются <code>X-Mock-Sandbox</code>. TTL <strong>самой песочницы</strong> остаётся на wall-clock ядра. Демо-документы задаются смещением от базы стенда (<code>MOCK_VIRTUAL_CLOCK</code> либо wall-clock), поэтому окно 10 суток не «устаревает» вместе со стендом <strong>[FORK]</strong>. <code>GET /admin</code> — read-only консоль, <code>/admin/journal</code> — журнал без тела Login, <code>Session-Token</code>, <code>Integrator-ID</code> и raw headers. Исходящих запросов у сервиса нет: ни callback, ни webhook, поэтому очередь доставки ядра и SSRF-политика к адаптеру не подключаются.</p><h2 id="_6-Песочницы-и-mock-control-не-api-провайдера" tabindex="-1">6. Песочницы и mock control (не API провайдера) <a class="header-anchor" href="#_6-Песочницы-и-mock-control-не-api-провайдера" aria-label="Permalink to &quot;6. Песочницы и mock control (не API провайдера)&quot;">​</a></h2><p>В self-hosted режиме без токенов control открыт локально. Для hosted: <code>MOCK_HOSTED=1</code>, tenancy по умолчанию <code>owned</code>; <code>/admin</code> fail-closed без <code>MOCK_ADMIN_TOKEN</code>, <code>/mock/*</code> — без operator/admin-токена или собственного owner-token. <code>GET /health</code>, <code>/openapi.json</code> и создание песочницы публичны.</p><p><code>POST /sandboxes</code> с <code>{&quot;id&quot;:&quot;reader-a&quot;}</code> в owned выдаёт <code>ownerToken</code> и <code>creds: {login, password, integratorId}</code>. В каждом запросе передавайте:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X-Mock-Sandbox: reader-a</span></span>
<span class="line"><span>X-Sandbox-Token: &lt;ownerToken&gt;</span></span>
<span class="line"><span>Integrator-ID: &lt;creds.integratorId этой песочницы&gt;   # на Login</span></span>
<span class="line"><span>Session-Token: &lt;token этой песочницы&gt;                # на чтение</span></span></code></pre></div><p>Знание sandbox ID доступа не даёт; чужой owner-token и чужой <code>Session-Token</code> отклоняются независимо. <code>GET /sandboxes/me</code> — метаданные без повторного раскрытия кредов; <code>POST /sandboxes/me/reset</code> — восстановить fixtures и отозвать маркеры; <code>POST /sandboxes/me/reset-creds</code> — новые mock-креды и отзыв маркеров (owner-token сохраняется); <code>DELETE /sandboxes/me</code> — удалить песочницу. <code>/mock/sandboxes</code> — operator alias.</p><p><code>GET /mock/state</code> экспортирует fixtures (<strong>без маркеров</strong>). <code>PUT /mock/state</code> импортирует snapshot <code>{accounts:[], kkt:[], documents:[], clockOffsetMs:0}</code> (или <code>{state: snapshot}</code>) и отзывает сессии: используйте экспорт как шаблон, сохраняя <code>an</code>/<code>kktRegNumber</code>/<code>accessible</code>, валидные ISO-даты <code>receivedAt</code>/<code>dateTime</code> и целочисленные суммы в копейках. Не импортируйте реальные ФД и ПДн. Это <strong>только mock-control</strong>, не выдуманный provider endpoint создания чека. <code>POST /mock/reset</code> сбрасывает текущую песочницу; сброс чужой — запрещён. State files содержат маркеры и сгенерированные mock-креды: ограничьте доступ к volume. <a href="./../../SECURITY">Модель угроз</a>.</p><h2 id="_7-Что-мок-проверяет-за-вас-границы-и-проверка" tabindex="-1">7. Что мок проверяет за вас: границы и проверка <a class="header-anchor" href="#_7-Что-мок-проверяет-за-вас-границы-и-проверка" aria-label="Permalink to &quot;7. Что мок проверяет за вас: границы и проверка&quot;">​</a></h2><p><code>npm run test:taxcom</code> — zero-dep HTTP selftest на эфемерных портах: Login (<code>Integrator-ID</code>, <strong>[VERIFY]</strong>-форма тела, неверные креды), sliding TTL 300 с и <code>401</code> по истечении, <code>AccountList</code>, <code>NewDocuments</code> (окно 10 суток, сортировка по <code>receivedAt</code>, курсор, хвост → пустой ответ, лимит 10 000 на 10 001 документе, 3106/2203, неизвестный <code>an</code>), read-only границы 405/404, сценарии, изоляция песочниц, owned-режим и ротация кредов, квота сессий, persist/restore, секреты и независимые негативные drift-контроли. Он включён в <code>npm test</code>; <code>check:drift</code> сверяет отдельную таблицу dispatch с OpenAPI, а не присваивает <code>inOpenApi=inServer</code>.</p><p>Не покрыто: реальный тестовый контур и его закрытые схемы, метод чтения одного ФД по ID (публичный URL не подтверждён), статистика, агрегаты смены со ставками 22%/22-122, права/роли в полном объёме. Write API, печать и callback <strong>не моделируются</strong>. Все локальные решения перечислены как <code>[VERIFY]</code>/<code>[FORK]</code> выше и в манифесте; проверка соответствия стенду провайдера не заявляется.</p><h2 id="_8-Ссылки" tabindex="-1">8. Ссылки <a class="header-anchor" href="#_8-Ссылки" aria-label="Permalink to &quot;8. Ссылки&quot;">​</a></h2><ul><li>Контракт сервиса, env и <code>/mock/*</code>: <a href="./../../services/taxcom-mock/README"><code>services/taxcom-mock/README.md</code></a></li><li>OpenAPI 3.1: <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/taxcom-mock.openapi.json" target="_blank" rel="noreferrer"><code>docs/openapi/taxcom-mock.openapi.json</code></a></li><li>Манифест протокола для <code>npm run check:drift</code>: <a href="https://github.com/rucorp/mock-services/blob/main/protocols/taxcom-ofd.json" target="_blank" rel="noreferrer"><code>protocols/taxcom-ofd.json</code></a></li><li>Общая инфраструктура адаптеров (часы, песочницы, вебхуки, SSRF): <a href="./../../packages/core/README"><code>packages/core/README.md</code></a></li></ul>`,46)])])}const g=e(a,[["render",c]]);export{k as __pageData,g as default};
